/**
 * @file    font.c
 * @brief   字库管理实现
 *
 * ASCII: 内嵌 8×16 字体 (0x20~0x7E, 95 字符)
 * 中文: GB2312 区位码 -> Flash 字模偏移计算
 *       (字模数据需由外部工具生成后编译进 font_data.c)
 *
 * 区位码映射: GB2312 内码 = 0xA1A1 + (区号-1)*94 + (位号-1)
 *             字模起始偏移 = ((区号-16)*94 + (位号-1)) * 32
 *             (跳过 1~15 区非汉字内容)
 */

#include "font.h"

